191	    public void disposeCompilerLocal(int localId) {
192	        if (localId >= localVariableCount) {
193	            throw new CompilerError("Trying to dispose of local " + localId +
194	                                       " but current metadata is off\nlocalVariableCount = " +
195	                                       localVariableCount +
196	                                       "\nvarNames = " + varNames);
197	        }
198	        String ty = varTypes.get(localId);
199	        if (ty != null) {
200	            Label finish = new Label();
201	            visitLabel(finish);
202	            visitLocalVariable(varNames.get(localId), ty, null, varFirstUse.get(localId), finish, localId);
203	        }
204	        Debug.debug(Debug.Type.CODEGEN, 2,
205	                    "LOCAL destroy ", localId, " ", varNames.get(localId));
206	        if (localId == (localVariableCount-1)) {
207	            varNames.remove(localId);
208	            varTypes.remove(localId);
209	            varFirstUse.remove(localId);
210	            localVariableCount--;
211	        } else {
212	            varNames.set(localId, null);
213	            varTypes.set(localId, null);
214	            varFirstUse.set(localId, null);
215	        }
216	    }
