   121	        	String params = desc.substring(desc.indexOf("(") +1,  //TODO: wrong if nested parens
   122	        								   desc.indexOf(")"));
   123	        	String newParams = newDesc.substring(newDesc.indexOf("(") +1,
   124						   							 newDesc.indexOf(")"));
   125	        	if(params.split(";").length == 1 && //single generic parameter 
   126	        			newParams.startsWith("LTuple")) {  //tuple substituted in
   127	        		//System.out.println(access + " " + name + " " + signature + " " +this.instanceName);
   128	        		if ( (this.access_flags & Opcodes.ACC_INTERFACE) == 0 &&  //not in an interface
   129	        			 (access & Opcodes.ACC_STATIC) == 0) {  //and not a static method, so generate a body  
   130	
   131	        			//extract the parameters and create strings for the types 
   132	        			List<String> paramList = 
   133	        					InstantiationMap.extractStringParameters(newParams, 
   134	        															 newParams.indexOf(Naming.LEFT_OXFORD), 
   135	        															 InstantiationMap.templateClosingRightOxford(newParams), 
   136	        															 new ArrayList<String>());			
   137	        		    String rawParams = "";
   138	        		    for (String p : paramList) rawParams = rawParams + Naming.internalToDesc(p);
   139	        		    final String altDesc = newDesc.substring(0,newDesc.indexOf("(")+1) + 
   140	        		    						rawParams + 
   141	        		    						newDesc.substring(newDesc.indexOf(")"), newDesc.length());        		    
   142	        		    String tuple_params = InstantiatingClassloader.stringListToTuple(paramList);
   143	        		    String make_sig = InstantiatingClassloader.toJvmSig(paramList, Naming.javaDescForTaggedFortressType(tuple_params));
   144	        		    
   145	        		    MethodVisitor altMv = cv.visitMethod(access, name, altDesc, signature, exceptions);
   146	        		    
   147	        		    altMv.visitVarInsn(Opcodes.ALOAD, 0); //load this
   148	        		    
   149	        			final int n = paramList.size();     //load the parameters
