   152	        		    }
   153	        		    altMv.visitMethodInsn(Opcodes.INVOKESTATIC, InstantiatingClassloader.CONCRETE_ + tuple_params, "make", make_sig);  //create a tuple from the parameters
   154	        		    
   155	        		    if (name.equals("<init>")) {
   156	                        altMv.visitMethodInsn(Opcodes.INVOKESPECIAL, this.instanceName, name, newDesc);     //call original method
   157	                        altMv.visitInsn(Opcodes.RETURN); //return
   158	        		    } else {
   159	                        altMv.visitMethodInsn(Opcodes.INVOKEVIRTUAL, this.instanceName, name, newDesc);     //call original method
   160	                        altMv.visitInsn(Opcodes.ARETURN); //return
   161	        		    }
   162	                    altMv.visitMaxs(Naming.ignoredMaxsParameter, Naming.ignoredMaxsParameter);
   163	        		    altMv.visitEnd();   
   164	        		}
   165	        	} 
   166	        }
