    93		private static byte[] UTF16toMUTF8(char c) {
    94			
    95			if ('\u0001' <= c && c <= '\u007f') {
    96				byte[] enc = {(byte) c};
    97				return enc;
    98			}
    99			if ('\u0080' <= c && c <= '\u07ff') { 
   100				byte b1 = (byte) (((c & 0x70c) >>> 6) | 0xc0);
   101				byte b2 = (byte) ((c & 0x3f) | 0x80);
   102				byte[] enc = {b1 , b2};
   103				return enc;
   104			}
   105			if ('\u0800' <= c && c <= '\uffff') { 
   106				byte b1 = (byte) (((c & 0xf000) >>> 12)| 0xe0);
   107				byte b2 = (byte) (((c & 0xfc0) >>> 6) | 0x80);
   108				byte b3 = (byte) ((c & 0x3f) | 0x80);
   109				byte[] enc = { b1 , b2 , b3 };
   110				return enc;
   111			}
   112			if ('\u0000' == c) { 
   113				byte b1 = (byte) (0 | 0xc0);
   114				byte b2 = (byte) (0 | 0x80);
   115				byte[] enc = {b1 , b2};
   116				return enc;
   117			}
